<template>
  <section class="panel"><div class="panel-head"><div><h2>規則設定</h2><p>按對象查看適用範圍、計算方式和提醒設定。</p></div><button class="button primary" @click="openNew">＋ 新增自訂規則</button></div>
    <div v-for="[scope, title] in scopes" :key="scope" class="rule-group"><h3>{{ title }}</h3><div class="table-wrap"><table class="rule-table"><thead><tr><th>事項</th><th>適用於</th><th>怎樣計算</th><th>提前提醒</th><th>客戶看得到</th><th>啟用</th><th>操作</th></tr></thead><tbody><tr v-for="rule in rules.filter(item => item.scope === scope)" :key="rule.id"><td data-label="事項"><strong>{{ rule.name }}</strong></td><td data-label="適用於">{{ appliesTo(rule) }}</td><td data-label="怎樣計算">{{ calculation(rule) }}</td><td data-label="提前提醒">{{ rule.remind_days }} 天</td><td data-label="客戶看得到"><label class="switch"><input type="checkbox" :checked="!!rule.customerVisible" :disabled="saving === rule.id" :aria-label="`${rule.name}客戶看得到`" @change="toggle(rule, 'customerVisible', $event)" /><span>{{ rule.customerVisible ? '是' : '否' }}</span></label></td><td data-label="啟用"><label class="switch"><input type="checkbox" :checked="!!rule.active" :disabled="saving === rule.id" :aria-label="`${rule.name}啟用`" @change="toggle(rule, 'active', $event)" /><span>{{ rule.active ? '啟用' : '停用' }}</span></label></td><td data-label="操作"><button class="button" @click="edit(rule)">編輯</button></td></tr></tbody></table></div></div>
  </section>
  <div v-if="dialog" class="overlay" @click.self="dialog = false"><div class="dialog"><div class="dialog-head"><div><div class="eyebrow">RULE SETTINGS</div><h2>{{ editing ? '編輯規則' : '新增自訂規則' }}</h2></div><button class="close" @click="dialog = false">×</button></div><div class="form-grid"><label v-if="!editing">規則代碼<input v-model="form.code" :placeholder="suggestedCode || '例如 annual_check'" /><small v-if="suggestedCode">建議代碼：{{ suggestedCode }}</small></label><label>規則名稱<input v-model="form.name" @input="suggestCode" /></label><label v-if="!editing">對象<select v-model="form.scope"><option v-for="[scope, title] in scopes" :key="scope" :value="scope">{{ title }}</option></select></label><label v-if="!editing">計算方式<select v-model="form.method" @change="resetParams"><option v-for="[method, title] in methods" :key="method" :value="method">{{ title }}</option></select></label><label>提醒天數<input v-model.number="form.remindDays" type="number" min="0" max="730" /></label><label v-for="[key, title] in matchFields" :key="key">適用條件：{{ title }}<input v-model="conditions[key]" placeholder="全部；多個可用、分隔" /></label><div v-if="editing && form.paramsField === 'cardExpiresOn'" class="rule-source-note">資料來源：批文卡有效期（不可在此修改）</div><template v-else-if="form.method === 'yearly'"><label>月份<input v-model.number="params.month" type="number" min="1" max="12" /></label><label>日期<input v-model.number="params.day" type="number" min="1" max="31" /></label></template><label v-else-if="form.method === 'anniversary'">周年偏移天數<input v-model.number="params.offsetDays" type="number" /></label><template v-else-if="form.method === 'inspection'"><label>領標誌年份<input v-model="markYears" /></label><label>上線檢驗年份<input v-model="inspectYears" /></label><label>每年檢驗起始年<input v-model.number="params.yearlyFrom" type="number" /></label></template><template v-else-if="form.method === 'periodic'"><label>週期月份<input v-model="periodicMonths" /></label><label>官方網址<input v-model="params.officialUrl" /></label></template></div><div class="dialog-actions"><button class="button" @click="dialog = false">取消</button><button class="button primary" @click="save">儲存規則</button></div></div></div>
</template>
<script setup>
import { ref, onMounted } from 'vue'
import { api } from '../api'
const emit = defineEmits(['error', 'saved'])
const scopes = [['plate', '兩地牌'], ['vehicle', '車輛'], ['company', '公司']]
const methods = [['expiry', '手動到期日'], ['yearly', '每年固定日期'], ['anniversary', '成立周年'], ['inspection', '驗車週期'], ['periodic', '定期核對']]
const matchFields = [['route', '路線'], ['jurisdiction', '司法區'], ['companyStatus', '公司狀態'], ['indicatorCategory', '指標類別'], ['port', '口岸'], ['origin', '車輛來源地']]
const rules = ref([]), editing = ref(''), dialog = ref(false), saving = ref(''), form = ref({}), conditions = ref({}), params = ref({}), markYears = ref(''), inspectYears = ref(''), periodicMonths = ref(''), suggestedCode = ref('')
const codeFromName = name => String(name || '').toLowerCase().replace(/[^a-z0-9\u4e00-\u9fff]+/g, '_').replace(/[\u4e00-\u9fff]/g, 'rule').replace(/^_+|_+$/g, '').slice(0, 40).replace(/^[^a-z]+/, 'rule_') || 'custom_rule'
function suggestCode() { if (!editing.value) suggestedCode.value = codeFromName(form.value.name) }
function resetParams() { params.value = form.value.method === 'yearly' ? { month: 1, day: 1 } : form.value.method === 'anniversary' ? { offsetDays: 0 } : form.value.method === 'inspection' ? { yearlyFrom: 10 } : form.value.method === 'periodic' ? { months: [1, 4, 7, 10], officialUrl: 'https://www.gsxt.gov.cn/' } : {} }
function openNew() { editing.value = ''; suggestedCode.value = ''; form.value = { code: '', name: '', scope: 'plate', method: 'expiry', remindDays: 30, active: true, customerVisible: true }; conditions.value = {}; resetParams(); markYears.value = '2,4,8'; inspectYears.value = '6'; periodicMonths.value = '1、4、7、10'; dialog.value = true }
async function load() { try { rules.value = await api('/rules') } catch (error) { emit('error', error) } }
function edit(rule) { editing.value = rule.id; form.value = { name: rule.name, scope: rule.scope, method: rule.method, remindDays: rule.remind_days, active: !!rule.active, customerVisible: !!rule.customerVisible, paramsField: rule.params.field }; conditions.value = Object.fromEntries(Object.entries(rule.match).map(([key, value]) => [key, Array.isArray(value) ? value.join('、') : value])); params.value = { ...rule.params }; markYears.value = rule.params.markYears?.join('、') || ''; inspectYears.value = rule.params.inspectYears?.join('、') || ''; periodicMonths.value = rule.params.months?.join('、') || ''; dialog.value = true }
const text = value => Array.isArray(value) ? value.join('、') : value
function appliesTo(rule) { const match = rule.match || {}; const base = rule.scope === 'plate' ? match.route?.includes?.('粵港') || match.route === '粵港' ? '粵港兩地牌' : match.route?.includes?.('粵澳') || match.route === '粵澳' ? '粵澳兩地牌' : '全部兩地牌' : rule.scope === 'vehicle' ? match.origin ? `${text(match.origin)}車輛` : '全部車輛' : match.jurisdiction ? `${text(match.jurisdiction)}公司` : '全部公司'; const details = Object.entries(match).filter(([key]) => !['route', 'origin', 'jurisdiction'].includes(key)).map(([key, value]) => key === 'companyStatus' ? `不含${['已註銷', '註銷中', '經營異常', '存續'].filter(status => !String(text(value)).includes(status)).join('、') || '其他狀態'}` : `${matchFields.find(entry => entry[0] === key)?.[1] || key}：${text(value)}`); return details.length ? `${base}（${details.join('；')}）` : base }
function calculation(rule) { const value = rule.params || {}; if (value.field === 'cardExpiresOn') return '按批文卡有效期'; if (rule.method === 'expiry') return '手動填寫到期日'; if (rule.method === 'anniversary') return `成立周年日後 ${value.offsetDays || 0} 天`; if (rule.method === 'yearly') return `每年 ${value.month} 月 ${value.day} 日`; if (rule.method === 'periodic') return `每季（${(value.months || []).join('、')} 月）`; if (rule.method === 'inspection') return `按車齡：第 ${(value.markYears || []).join('、')} 年領檢驗標誌，第 ${(value.inspectYears || []).join('、')} 年上線驗車，第 ${value.yearlyFrom} 年起每年驗車`; return '依規則計算' }
async function toggle(rule, field, event) { const enabled = event.target.checked; saving.value = rule.id; try { await api(`/rules/${rule.id}`, 'PATCH', { [field]: enabled }); rule[field] = enabled; emit('saved', '規則已更新') } catch (error) { event.target.checked = !!rule[field]; emit('error', error) } finally { saving.value = '' } }
async function save() { try { const match = Object.fromEntries(Object.entries(conditions.value).filter(([, value]) => String(value || '').trim()).map(([key, value]) => [key, String(value).split(/[、,]/).map(part => part.trim()).filter(Boolean)])); const values = { ...params.value }; if (form.value.method === 'inspection') { values.markYears = markYears.value.split(/[、,]/).filter(Boolean).map(Number); values.inspectYears = inspectYears.value.split(/[、,]/).filter(Boolean).map(Number) } if (form.value.method === 'periodic') values.months = periodicMonths.value.split(/[、,]/).filter(Boolean).map(Number); const body = { ...form.value, code: form.value.code || suggestedCode.value, match, params: values }; delete body.paramsField; if (editing.value) { delete body.scope; delete body.method; delete body.code; delete body.active; delete body.customerVisible } await api(editing.value ? `/rules/${editing.value}` : '/rules', editing.value ? 'PATCH' : 'POST', body); dialog.value = false; await load(); emit('saved', '規則已儲存') } catch (error) { emit('error', error) } }
onMounted(load)
</script>
